class Solution {
    public TreeNode buildTree(int[] preorder, int[] inorder) {
        return build(preorder, inorder, 0, preorder.length - 1, 0, inorder.length - 1);
    }

    private TreeNode build(int[] preorder, int[] inorder,
                           int preLo, int preHi, int inLo, int inHi) {
        if (preLo > preHi) return null;

        int rootVal = preorder[preLo];
        TreeNode root = new TreeNode(rootVal);

        // 线性查找根在中序中的位置
        int rootIdx = inLo;
        for (int i = inLo; i <= inHi; i++) {
            if (inorder[i] == rootVal) { rootIdx = i; break; }
        }

        int leftSize = rootIdx - inLo;
        root.left  = build(preorder, inorder, preLo + 1, preLo + leftSize, inLo, rootIdx - 1);
        root.right = build(preorder, inorder, preLo + leftSize + 1, preHi, rootIdx + 1, inHi);
        return root;
    }
}

import java.util.*;

class Solution {
    private Map<Integer, Integer> indexOf = new HashMap<>();
    private int preIdx = 0;
    private int[] preorder;

    public TreeNode buildTree(int[] preorder, int[] inorder) {
        this.preorder = preorder;
        for (int i = 0; i < inorder.length; i++) indexOf.put(inorder[i], i);
        return build(0, inorder.length - 1);
    }

    private TreeNode build(int inLo, int inHi) {
        if (inLo > inHi) return null;

        int rootVal = preorder[preIdx++];
        TreeNode root = new TreeNode(rootVal);

        int rootIdx = indexOf.get(rootVal);
        root.left  = build(inLo, rootIdx - 1);    // 必须先左再右
        root.right = build(rootIdx + 1, inHi);
        return root;
    }
}

import java.util.*;

class Solution {
    public TreeNode buildTree(int[] preorder, int[] inorder) {
        if (preorder.length == 0) return null;

        TreeNode root = new TreeNode(preorder[0]);
        Deque<TreeNode> stack = new ArrayDeque<>();
        stack.push(root);

        int inIdx = 0;
        int n = inorder.length;

        for (int i = 1; i < n; i++) {
            TreeNode node = stack.peek();

            if (node.val != inorder[inIdx]) {
                // 还在往左钻
                node.left = new TreeNode(preorder[i]);
                stack.push(node.left);
            } else {
                // 左链到底，开始往上爬
                while (!stack.isEmpty() && inIdx < n
                        && stack.peek().val == inorder[inIdx]) {
                    node = stack.pop();
                    inIdx++;
                }
                node.right = new TreeNode(preorder[i]);
                stack.push(node.right);
            }
        }
        return root;
    }
}
